Class Empleado
  Define nombre As String;

  Method Constructor(n As String)
    This.nombre <- n;
  EndMethod

  Method Presentarse() As String
    Return "Hola, soy " + This.nombre;
  EndMethod
EndClass

Class Cajero Inherits From Empleado
  Method Constructor(n As String)
    Super.constructor(n);
  EndMethod

  Method Presentarse() As String
    Return Super.Presentarse() + " y atiendo la caja";
  EndMethod
EndClass

Algorithm Kiosco
  Define nombre, puesto As String;
  Read nombre;
  Read puesto;
  Define persona As Empleado <- New Empleado(nombre);
  If puesto = "cajero" Then
    persona <- New Cajero(nombre);
  EndIf
  Write persona.Presentarse();
EndAlgorithm
